#include "AlertRuntime.hpp"
namespace elysium::fortress {void AlertRuntime::signal(AlertKey k,AlertPriority p,std::uint64_t t,ContentId r){auto i=rows_.find(k);if(i==rows_.end())rows_.emplace(k,Alert{k,p,t,t,1,false,false,false,true,r});else{auto&a=i->second;a.last=t;++a.count;a.active=true;if(std::uint8_t(p)>std::uint8_t(a.priority))a.priority=p;a.reason=r;}}bool AlertRuntime::clear(AlertKey k,std::uint64_t t){auto i=rows_.find(k);if(i==rows_.end())return false;i->second.last=t;i->second.active=false;return true;}bool AlertRuntime::acknowledge(AlertKey k){auto i=rows_.find(k);if(i==rows_.end())return false;i->second.acknowledged=true;return true;}std::vector<Alert>AlertRuntime::active()const{std::vector<Alert>v;for(auto&[_,a]:rows_)if(a.active&&!a.muted)v.push_back(a);std::sort(v.begin(),v.end(),[](auto&a,auto&b){return std::uint8_t(a.priority)==std::uint8_t(b.priority)?a.first<b.first:std::uint8_t(a.priority)>std::uint8_t(b.priority);});return v;}}
